def count_divisors(n: int) -> int:
    """Return the number of positive divisors of n."""
    if n <= 0:
        raise ValueError("n must be a positive integer")

    # Count divisors up to sqrt(n) and mirror them.
    i = 1
    count = 0

    while i * i <= n:
        remainder = n % i
        if remainder == 0:
            # If divisor is perfect square, add once; otherwise twice (i and n//i).
            if i * i == n:
                count += 1
            else:
                count += 2
        i += 1

    return count


# Example assertion from the problem statement
assert count_divisors(15) == 4

